  controller:{path:'backend/src/main/java/com/reeb/llmstudio/learning',file:'LearningController.java',lang:'Java · Spring Web',role:'Puerta de entrada HTTP del laboratorio',pattern:'Controller delgado: recibe el contrato HTTP y delega las reglas al servicio.',definition:'Cada endpoint es un contrato. @Valid rechaza una entrada inválida antes de que llegue a la lógica de negocio.',trace:['GET /api/modules','LearningController.modules()','LearningService.modules()','ModuleRepository','JSON para Angular'],code:['@RestController','@RequestMapping("/api")','public class LearningController {','  private final LearningService service;','','  @GetMapping("/modules")','  public List<LearningDtos.ModuleResponse> modules() {','    return service.modules();','  }','','  @PostMapping("/challenges/validate")','  public LearningDtos.ChallengeResponse validate(','      @Valid @RequestBody LearningDtos.ChallengeRequest request) {','    return service.validate(request);','  }','}'].join('\n')},
